		public override void update()
		{
			base.update();
			if (!gecis && player.x > 360)
			{
				FlxG.playMusic(music, 1);
				gecis = true;
			}

			FlxG.collide(player, blocks);
			FlxG.overlap<MonsterHans, Door>(monsters, interacts, monsterHansWithDoor);
		}

		public void monsterHansWithDoor(MonsterHans Sprite1, Door Sprite2)
		{
			if (player.fading && !monsterhansdoor)
			{
				Sprite2.kill();
				monsterhansdoor = true;
				monsterhans.fading = true;
			}
		}

		public override void getWell()
		{
			FlxG.bgColor = 4288900388;
		}

		public override void nextLevel()
		{
			FlxG.switchState(new Level37());
		}

